create or replace function public.get_or_create_american_assignment_unit(p_category public.american_category) returns uuid language plpgsql security definer set search_path=public as $$
declare unit_id uuid;begin if public.app_current_role()<>'teacher' then raise exception 'forbidden';end if;select id into unit_id from question_bank_units where teacher_id=auth.uid() and education_system='american' and american_category=p_category and title='__American Assignments' order by created_at limit 1;if unit_id is null then insert into question_bank_units(teacher_id,title,description,education_system,national_grade,american_category) values(auth.uid(),'__American Assignments','Internal assignment question workspace','american',null,p_category) returning id into unit_id;end if;return unit_id;end $$;
revoke all on function public.get_or_create_american_assignment_unit(public.american_category) from public,anon;
grant execute on function public.get_or_create_american_assignment_unit(public.american_category) to authenticated;
